pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 preBalance, uint128 depositAmount) public {
        vm.assume(preBalance <= type(uint256).max - depositAmount);
        address actor = address(0x1000);
        vm.deal(actor, depositAmount);
        // set up pre-existing balance via deposit
        if (preBalance > 0) {
            vm.deal(actor, preBalance);
            vm.prank(actor);
            c.deposit{value: preBalance}();
        }
        // record balance before second deposit
        uint256 balanceBefore = c.balances(actor);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        uint256 balanceAfter = c.balances(actor);
        assertEq(balanceAfter, balanceBefore + depositAmount, "balance increment must equal deposit amount");
    }
}

