pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. Restrict to admissible domain (keep it wide, only exclude zero to make overflow reachable faster)
        vm.assume(amount > 0);
        address actor = address(0x100);
        vm.deal(actor, amount);

        // 2. Ensure the sender's balance starts at a value that, when added to amount, overflows uint256.
        // We can't use vm.store because it's rejected, but we can call deposit() with an amount that sets
        // up a near-max balance, then deposit(amount) to trigger overflow.
        // Set initial balance to type(uint256).max - amount + 1, so that adding amount overflows.
        uint256 setupAmount = type(uint256).max - amount + 1;
        // Need enough Ether for setup deposit.
        vm.deal(address(c), setupAmount); // give the contract Ether so transfer in withdraw works if needed (we won't withdraw)
        vm.prank(actor);
        vm.deal(actor, setupAmount);
        c.deposit{value: setupAmount}();
        // Now c.balances(actor) == setupAmount.

        // 3. Deposit the fuzzed amount, which will cause overflow.
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // 4. Assert: balance after deposit >= amount
        uint256 finalBalance = c.balances(actor);
        assertTrue(finalBalance >= amount);
    }
}

