pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        // Bound the amount to avoid overflow in the invariant computation (keep it wide)
        amount = bound(amount, 0, type(uint128).max);
        // Actor must be a valid, non-zero address and distinct from the contract
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.deal(actor, amount);

        // Compute total Ether balance of contract and sum of all user balances before deposit
        uint256 balanceBefore = address(c).balance;
        // Since only the actor will have a balance in this isolated fuzz run,
        // we sum all possible balances by simply reading the actor's mapping entry.
        // (The contract's balances mapping is not directly iterable; the invariant
        // must hold for any state. We deposit for this single actor and check
        // that the total balance matches the sum of all balances, which is
        // just the actor's balance after the deposit plus any pre-existing balances
        // from zero or other actors. To keep the invariant computable without
        // iterating the mapping, we use a helper approach: after deposit,
        // we call a view function that returns the sum of all balances.
        // However, C has no such function. Instead, we use a different formulation
        // that does not require iterating: after deposit, the caller's balance
        // must be at least the amount deposited plus any prior balance.
        // But the tried approaches reject that.
        // We must state a general rule. The bug: deposit() does not update
        // balances[msg.sender], so the sum of all balances is unchanged, but
        // the contract's ETH balance increases by msg.value. Therefore, for any
        // state, after a deposit, the contract's total ETH balance must equal
        // the sum of all recorded balances (which we can compute by calling
        // a public function that reads the mapping of the single actor we control).
        // Since the contract has no public sum function, we can deploy a helper
        // that wraps C and exposes a function to compute the sum by querying
        // all known users. But we cannot iterate all addresses.
        // Alternative: we use vm.prank to deposit from actor, then assert that
        // address(c).balance == balances[actor] (since only this actor has interacted
        // in this test, and no other balances exist). This holds in the reference
        // contract because deposit increases balances[actor] by amount, so
        // after deposit, balance == balances[actor]. In the buggy version,
        // balances[actor] is not increased, so address(c).balance > balances[actor].
        // This is a general rule for any admissible deposit: after deposit,
        // the contract's balance must equal the actor's balance (since no other
        // balances exist in this isolated scenario). The fuzzer provides the
        // amount and actor, so it's not hard-coded.

        vm.prank(actor);
        c.deposit{value: amount}();

        uint256 balanceAfter = address(c).balance;
        // Since balances is a public mapping, we can read it as c.balances(actor)
        // But the error shows c.balances is not visible? Wait, balances is a
        // public mapping, so Solidity auto-generates a getter balances(address).
        // The original error was about c.balances(actor) not found, which indicates
        // the source file might have a different visibility or the compiler
        // version issue. But we must follow the error: "Member "balances" not found
        // or not visible after argument-dependent lookup in contract C."
        // That suggests balances is not public in the under-test contract.
        // The given contract C indeed declares: mapping(address => uint256) balances;
        // without 'public' keyword, so it is internal by default, thus no getter.
        // Therefore, we cannot read c.balances(actor). We must compute the
        // invariant using only public/external surface. The contract has no
        // view function to read balances. We must use a different invariant.
        // The invariant must be about the contract's behavior. We can observe
        // the contract's ETH balance change. The bug: deposit does not update
        // balances[msg.sender], but since we cannot read balances, we cannot
        // directly compare. However, we can detect the bug by calling refund()
        // after deposit and checking the ETH returned. In the reference contract,
        // refund() sends the balance recorded for the caller (which is amount),
        // and sets it to 0, then transfers that amount. So after deposit then
        // refund (by the same actor), the actor's ETH balance should have
        // increased by 0 (since they deposited amount and got it back). In the
        // buggy contract, refund() reads balances[msg.sender]=0 (unchanged),
        // sends 0 ETH, and sets 0. So the actor loses the deposited amount.
        // We can assert that after deposit+refund, the actor's ETH balance is
        // equal to their initial balance (minus gas costs, but we can wrap
        // the calls and measure ETH difference). Or we can assert that after
        // deposit, the contract's balance is positive when amount>0, but that
        // is not a general rule (deposit always increases contract balance).
        // A general rule: "After a deposit, the sum of all user balances
        // (as internally recorded) must increase by the deposited amount."
        // But we can't read the sum. However, we can read the contract's
        // total ETH balance. Since the only payable functions are deposit
        // (and others that don't receive ETH), the contract's ETH balance
        // must equal the total of all recorded balances (since only deposit
        // adds ETH). That is the tried approach.
        // But we can implement the sum over a known set of users by using
        // a helper contract that iterates over an array of users that we
        // maintain. However, that is not allowed to import new things for
        // the helper? A helper can have an array of addresses that we add.
        // However, the invariant test must be general: for any deposit by
        // any actor, the rule holds. We can deploy a helper that tracks
        // users who have deposited, and provides a function to compute
        // the total balance in C. But C has no public mapping getter, so
        // the helper cannot read c.balances(user) either. The helper could
        // not read internal mapping. So not possible.
        // Instead, we use the fact that refund() reveals the internal
        // balance of the caller. We can assert: if a user deposits amount,
        // then calls refund, they should receive at least amount (since
        // their balance was amount). In the buggy version, they receive 0.
        // This can be observed via ETH difference. The rule: "After deposit
        // and subsequent refund by the same user, the net ETH change for
        // that user must be zero (excluding gas)." Since we can measure
        // the user's ETH balance before deposit and after refund, the
        // difference should be ~0 (gas costs ignored by measuring with
        // balance before and after inside the test, using vm.deal).
        // We can achieve this by:
        // 1. vm.deal(actor, amount)
        // 2. vm.prank(actor) c.deposit{value: amount}()
        // 3. uint256 actorBalanceAfterDeposit = actor.balance; // after deposit
        // 4. vm.prank(actor) c.refund();
        // 5. uint256 actorBalanceAfterRefund = actor.balance;
        // Assert: actorBalanceAfterRefund == amount + (initial balance after vm.deal) - gas costs? Hard.
        // We can instead assert that after refund, the actor's balance is
        // greater than zero when amount>0, but that's not a strict equality.
        // The general rule: "For any deposit amount > 0, the actor must be
        // able to withdraw a positive amount afterward." Since withdraw
        // requires balance > 0, and in buggy version balance is 0, withdraw
        // reverts. So we can assert that after deposit(amount>0), withdraw(anyAmount>0)
        // should succeed (specifically, withdraw(amount) should succeed).
        // In reference, withdraw(amount) succeeds because balance == amount.
        // In buggy, withdraw(any) reverts because balance == 0. So assert
        // that withdraw(amount) does not revert after deposit(amount).
        // This is a general rule: "After depositing a positive amount,
        // withdrawing that same amount should succeed."
        // This uses only public functions and revert booleans.
        // We can fuzz amount (positive) and actor, deposit, then try withdraw,
        // and assert that it does not revert.
        // That rule holds for reference C but fails for buggy when amount>0.
        // So the test:
        // - vm.assume(amount > 0)
        // - vm.deal(actor, amount)
        // - vm.prank(actor); c.deposit{value: amount}();
        // - vm.prank(actor); bool ok = true; try c.withdraw(amount) {} catch { ok = false; }
        // - assertTrue(ok);
        // This satisfies all requirements? The rule: "After deposit, the user can withdraw the deposited amount."
        // Bug breaks it because balance not updated.
        // But note: the tried approaches list did not include this exact one;
        // it listed balances-related invariants. This is different.
        // However, the property must be about reading c's public surface.
        // The assertTrue(ok) reads the revert boolean from c.withdraw, which
        // is a public function call. Ok.
        // The fuzzed params: amount, actor.
        // No adversarial helper needed; withdraw is an internal call, no external party that fails.
        // So final code below.

        vm.assume(amount > 0);
        vm.deal(actor, amount);

        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        bool ok = true;
        try c.withdraw(amount) {
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

