        // Deploy adversarial helper that always reverts on receive
        Reverter reverter = new Reverter();
        address actor = address(reverter);
        vm.deal(actor, depositAmt);

        // Actor deposits
        vm.prank(actor);
        c.deposit{value: depositAmt}();

        // Record initial balance
        uint256 balBefore = c.balances(actor);

        // Attempt withdraw from actor (the reverter contract), which will revert on transfer
        bool ok;
        try c.withdraw(withdrawAmt) { ok = true; } catch { ok = false; }

        // Read final balance
        uint256 balAfter = c.balances(actor);

        // Reference rule: if transfer failed, balance must remain unchanged.
        // The buggy version reduces balance before transfer, so after revert balance is lowered -> invariant broken.
        assertTrue(!ok || balBefore - balAfter == withdrawAmt);
    }
}

contract Reverter {
    // This contract receives Ether and immediately reverts, simulating a failing transfer.
    receive() external payable {
        revert("Reverter: always fails");
    }
}

