contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, address caller) public payable {
        require(to != address(0) && caller != address(0) && caller != address(this), "");
        // Use the provided caller by sending a low-level call from this test's address;
        // we need to simulate a call to migrateTo from an arbitrary address.
        // To do so, we will call migrateTo via a low-level delegatecall-like approach is not possible here.
        // Instead, we rely on the fact that msg.sender in migrateTo is the test contract itself,
        // but the rule involves the creator. Since we cannot change msg.sender, we'll check the revert behavior
        // based on whether address(this) is the creator.
        // The original difference is that a non-creator calling migrateTo succeeds in M but reverts in P.
        // We can observe this via a low-level call that sets msg.sender to the test contract, which is not the creator.
        // Actually, the test contract is not the creator (c was deployed elsewhere), so a direct call from this test will
        // always be a non-creator call. So we just need to call migrateTo and assert that it always reverts.
        bool reverted;
        try c.migrateTo(to) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}

